"""1.6.0 Firnlab kit 1 (pages) on a COPY of the real data with the mock runtime. Never touches real data.
Covers: when the kit applies, the storage recommendation rule (three cases), the decision in the one queue (Pick deck, counts, options,
star on the recommendation, block once a package exists), answering (decision line, Undo, change marks the package), what the
design and compile prompts get, the build brief steps and PART F, the report's live version ids, the three new proof rules,
labels in three languages."""
import json, sys, pathlib, re
BK = sys.argv[1] if len(sys.argv) > 1 else "work/backup-141"
sys.argv = [sys.argv[0], BK]
__file__ = str(pathlib.Path(__file__).resolve().parent / "e2e14.py")
exec(open(__file__).read().split("with sync_playwright() as pw:")[0])
_check0 = check
def check(name, cond, info=""):
    _check0(name, cond, info); print(("ok    " if cond else "FAIL  ") + name + ("" if cond else "  → " + str(info)[:500]), flush=True)
def ev(pg, js, *a): return pg.evaluate(js, *a)

ARCH = """([home, extra]) => { const p = curP(); const ui = /page|artifact|web app/.test(home);
  p.arch.components = ui ? [{id: 'c1', name: 'Main page', kind: 'code', role: 'Shows the result', inputs: 'records', outputs: 'a page with the result', reason: '', reqIds: []},
  {id: 'c2', name: 'Scoring', kind: 'ai', role: 'Scores each idea', inputs: 'idea text', outputs: 'score', reason: '', reqIds: []}]
  : /scheduled|task/.test(home) ? [{id: 'c1', name: 'Mailer', kind: 'ai', role: 'writes the weekly mail', inputs: 'notes', outputs: 'one mail', reason: '', reqIds: []}] : [{id: 'c1', name: 'Logic', kind: 'code', role: 'computes the result', inputs: 'input', outputs: 'result', reason: '', reqIds: []}];
  if (extra && extra.raw){ p.intake.raw = extra.raw; delete extra.raw; }
  p.arch.options = [{id: 'o1', name: 'Page', kind: 'workflow', summary: '', scores: {}, pros: [], cons: []}]; p.arch.chosen = 'o1'; p.arch.recommended = 'o1';
  p.tool.home = {where: home, parts: ui ? 'the result on a page' : /scheduled|task/.test(home) ? 'a weekly mail' : 'the result', why: ''}; Object.assign(p, extra || {}); touch(p); render(); }"""

with sync_playwright() as pw:
    b = pw.chromium.launch()
    ctx = new_ctx(b); pg = open_page(ctx); pg.wait_for_timeout(300)
    print("1 when the kit applies")
    ev(pg, "(() => { newProject('Idea board', {raw: 'A board where I keep and score my ideas'}); UI.home = false; render(); })()")
    check("no design yet → no kit, no storage question", ev(pg, "!kitApplies(curP()) && !queueOf(curP()).some(x => x.kind === 'kit-storage')"))
    ev(pg, ARCH, ["scheduled task", None])
    check("a design without a page → the kit stays out", ev(pg, "!kitApplies(curP())"))
    ev(pg, ARCH, ["artifact page", None])
    q = ev(pg, "(() => { const x = queueOf(curP()).find(x => x.kind === 'kit-storage'); return x && {cls: x.cls, who: x.who, ph: x.ph, ref: x.ref, title: x.title, stage: x.stage}; })()")
    check("a page in the design → the storage decision waits in the queue (should, you, arch)", q and q["cls"] == "should" and q["who"] == "you" and q["ph"] == "arch" and q["ref"] == "kit:storage", q)
    # 1.8 (owner): where the data lives is "your call first" — the ★ on the recommendation shows after your own answer (was: ★ shown at once)
    check("…and in the Pick deck with three options; the ★ on the recommendation waits for your call", ev(pg, "(() => { const c = pickDeck(curP()).find(c => c.kind === 'kit-storage'), x = queueOf(curP()).find(x => x.kind === 'kit-storage'); return !!c && c.options.length === 3 && c.callFirst && c.rec === -1 && PK8_QO(curP(), x).findIndex(o => o.star) === KIT_STORAGE.indexOf(kitStorageRec(curP()).kind) && c.options.every(o => o.label && o.text); })()"))
    check("…and in the counts for you", ev(pg, "queueCounts(curP()).you") >= 1)
    check("the queue item has a name, not a raw id", ev(pg, "refLabel(curP(), 'kit:storage')") == ev(pg, "t('kit.q.storage')"))

    print("2 the recommendation rule")
    check("a board for me → the page is the record", ev(pg, "kitStorageRec(curP()).kind") == "artifact", ev(pg, "kitStorageRec(curP())"))
    ev(pg, ARCH, ["artifact page", {"raw": "A page that shows me the weather for my runs", "northStar": {"problem": "", "goal": "Show me the weather for my runs", "success": "", "users": "me", "constraints": "", "now": ""}}])
    check("private, small → this browser + export", ev(pg, "kitStorageRec(curP()).kind") == "local", ev(pg, "kitStorageRec(curP())"))
    ev(pg, ARCH, ["artifact page", {"raw": "A board my team and colleagues update", "northStar": {"problem": "", "goal": "A board my team and colleagues update", "success": "", "users": "me and my team", "constraints": "", "now": ""}}])
    check("other people → the page's storage (db)", ev(pg, "kitStorageRec(curP()).kind") == "db", ev(pg, "kitStorageRec(curP())"))
    ev(pg, ARCH, ["artifact page", {"raw": "A checklist for my move", "northStar": {"problem": "", "goal": "A checklist for my move", "success": "", "users": "me", "constraints": "", "now": ""}}])
    check("a checklist for me → the page is the record", ev(pg, "kitStorageRec(curP()).kind") == "artifact", ev(pg, "kitStorageRec(curP())"))
    ev(pg, ARCH, ["artifact page and a scheduled task", {"raw": "My private reading list", "northStar": {"problem": "", "goal": "My private reading list", "success": "", "users": "me", "constraints": "", "now": ""}}])
    check("a scheduled part reads the data → db", ev(pg, "kitStorageRec(curP()).kind") == "db", ev(pg, "kitStorageRec(curP())"))
    ev(pg, ARCH, ["artifact page", {"raw": "My private reading list", "northStar": {"problem": "", "goal": "My private reading list", "success": "", "users": "me", "constraints": "", "now": ""}}])
    check("the rule is deterministic", ev(pg, "[kitStorageRec(curP()).kind, kitStorageRec(curP()).kind]") == ["local", "local"])

    print("3 answering")
    n0 = ev(pg, "curP().decisions.length"); a0 = ev(pg, "arr(curP().acts).filter(a => !a.undone).length")
    r = ev(pg, "(async () => { const x = queueOf(curP()).find(x => x.kind === 'kit-storage'); const o = PK8_QO(curP(), x); const i = o.findIndex(y => y.star); return [await qDo(curP(), x, i), i]; })()")   # 1.8: the ★ is read from the options before your-call-first hides it
    check("the starred option is PT's recommendation", r[1] == ev(pg, "KIT_STORAGE.indexOf(kitStorageRec(curP()).kind)"), r)
    st = ev(pg, "kitStorageDecided(curP())")
    check("one click decides: stored with by=you and the recommendation it followed", st and st["kind"] == "local" and st["by"] == "you" and st["rec"] == "local", st)
    pg.wait_for_timeout(50)
    acts = ev(pg, "arr(curP().acts).filter(a => !a.undone).map(a => a.label)")
    check("one decision line, one Undo step", ev(pg, "curP().decisions.length") == n0 + 1 and len(acts) == a0 + 1, [n0, ev(pg, "curP().decisions.length"), a0, acts])
    check("the queue item is gone", ev(pg, "!queueOf(curP()).some(x => x.kind === 'kit-storage')"))
    ev(pg, "(() => { const a = arr(curP().acts).filter(a => !a.undone).slice(-1)[0]; undoAct(curP(), a.id); render(); })()")
    check("Undo takes the decision back and the question returns", ev(pg, "!kitStorageDecided(curP()) && queueOf(curP()).some(x => x.kind === 'kit-storage')"))
    ev(pg, "kitSetStorage(curP(), 'db')")
    check("your own choice is recorded as your own", ev(pg, "curP().decisions.slice(-1)[0].reason") == ev(pg, "t('kit.dec.own')"))
    ev(pg, "(() => { const p = curP(); p.pkg = {sections: [{id: 's1', dest: 'artifact', title: 'Board', content: 'build a board', reqIds: [], why: ''}, {id: 's2', dest: 'instructions', title: 'I', content: 'x', reqIds: [], why: ''}], targetModel: 'claude-opus-5-5', rationale: [], compiledAt: now()}; touch(p); })()")
    ev(pg, "kitSetStorage(curP(), 'artifact')")
    check("a changed decision marks the page section of the package, not the rest", ev(pg, "arr(curP().flags).map(f => f.ref)") == ["section:s1"])
    ev(pg, "(() => { const p = curP(); p.kit = {}; touch(p); })()")
    check("with a package and no decision the question blocks", ev(pg, "(queueOf(curP()).find(x => x.kind === 'kit-storage') || {}).cls") == "block")
    ev(pg, "kitSetStorage(curP(), 'db')")

    print("4 what the design, the package and the brief get")
    pr = ev(pg, "buildPrompt('architecture', {proj: curP(), rules: ['simple'], body: 'design', schema: '{}'})")
    check("the design prompt gets the page facts and the decision", "<kit_artifact" in pr and "DECIDED by the person" in pr and "ability \"db\"" in pr and "starts private" in pr and "firnlab/tools" in pr)
    pr2 = ev(pg, "buildPrompt('review', {proj: curP(), rules: ['simple'], body: 'review', schema: '{}'})")
    check("other prompts stay as they were", "<kit_artifact" not in pr2)
    ev(pg, "(() => { const p = curP(); p.kit = {}; })()")
    pr3 = ev(pg, "buildPrompt('compile', {proj: curP(), rules: ['simple'], body: 'compile', schema: '{}'})")
    check("undecided: the prompt names the recommendation as open", "not decided yet. Prompt Translator recommends" in pr3)
    ev(pg, "kitSetStorage(curP(), 'db')")
    brief = ev(pg, "buildBriefText(curP())")
    check("the brief has the page step with its check and the GitHub step", "Artifact page(s) · Firnlab kit 1" in brief and "390 px" in brief and "firnlab/tools/idea-board/index.html" in brief and "declare db and user" in brief)
    check("…PART F with the facts and the decision, and the versions field in the report", "PART F · ARTIFACT RULES" in brief and "decided by the person" in brief and '"versions":[{"url"' in brief)
    ev(pg, ARCH, ["scheduled task", None])
    check("no page → no page steps in the brief", "Firnlab kit 1" not in ev(pg, "buildBriefText(curP())"))
    ev(pg, ARCH, ["artifact page", None])

    print("5 the report keeps the live version ids")
    rep = ev(pg, "checkReport(curP(), {parts: [{id: 'c1', built: true}, {id: 'c2', built: true}], checks: [], tests: [], artifacts: ['https://claude.ai/artifact/abc'], versions: [{url: 'https://claude.ai/artifact/abc', version: '1792000000-aaaa'}, {url: 'https://evil.example/x', version: 'z'}, {url: 'https://claude.ai/artifact/abc'}], triggers: []})")
    check("only claude.ai urls with a version id are kept", rep["versions"] == [{"url": "https://claude.ai/artifact/abc", "version": "1792000000-aaaa"}], rep.get("versions"))
    ev(pg, "(() => { const p = curP(); p.report = {check: checkReport(p, {parts: [], checks: [], tests: [], artifacts: [], versions: [{url: 'https://claude.ai/artifact/abc', version: '1792000000-aaaa'}], triggers: []})}; kitRecordVersions(p, '1.0'); kitRecordVersions(p, '1.0'); })()")
    check("recorded once per url+version, with the release", ev(pg, "arr(curP().tool.versions).map(x => [x.version, x.v])") == [["1792000000-aaaa", "1.0"]])

    print("6 the new proof rules")
    modes = ev(pg, "proofModes(curP()).map(m => m.id)")
    check("a page tool gets consent, where and secret", all(m in modes for m in ["consent", "where", "secret"]), modes)
    ev(pg, ARCH, ["scheduled task", {"raw": "Send me a weekly e-mail with my notes", "northStar": {"problem": "", "goal": "Send me a weekly e-mail", "success": "", "users": "me", "constraints": "", "now": ""}}])
    ev(pg, "(() => { const p = curP(); p.arch.components = [{id: 'c1', name: 'Mailer', kind: 'ai', role: 'writes the mail', inputs: 'x', outputs: 'mail', reason: '', reqIds: []}]; })()")
    modes2 = ev(pg, "proofModes(curP()).map(m => m.id)")
    check("a tool without a screen does not", not any(m in modes2 for m in ["consent", "where", "secret"]), modes2)
    check("every new rule has a name and a line in three languages", ev(pg, "['consent','where','secret'].every(id => ['en','de','zh'].every(l => { const a = STR['pf.n.' + id], b = STR['pf.d.' + id]; return a && b && a[['en','de','zh'].indexOf(l)] && b[['en','de','zh'].indexOf(l)]; }))"))

    print("8 kit 2: scheduled tools")
    ev(pg, "(() => { newProject('Price radar', {raw: 'Every morning check three shop pages for price drops and tell me'}); UI.home = false; render(); })()")
    ev(pg, ARCH, ["scheduled task", {"raw": "Every morning check three shop pages for price drops and tell me", "northStar": {"problem": "", "goal": "Tell me about price drops every morning", "success": "", "users": "me", "constraints": "", "now": ""}}])
    check("a scheduled design → kit 2 applies, kit 1 does not", ev(pg, "kit2Applies(curP()) && !kitApplies(curP())"))
    qs = ev(pg, "queueOf(curP()).filter(x => x.kind.startsWith('kit-')).map(x => [x.kind, x.cls, x.who])")
    check("two decisions wait: engine and results (should, you)", sorted(qs) == [["kit-engine", "should", "you"], ["kit-results", "should", "you"]], qs)
    check("engine: hourly or slower → the included scheduled task", ev(pg, "kitEngineRec(curP()).kind") == "scheduled")
    check("results: nothing to approve, no table → a page", ev(pg, "kitResultsRec(curP()).kind") == "page")
    ev(pg, "(() => { const p = curP(); p.intake.raw = 'Check the prices every 10 minutes and draft an e-mail for me to approve'; p.northStar.goal = 'Price drops within minutes, drafts I approve'; })()")
    check("every 10 minutes → Managed Agent, with its cost on the option", ev(pg, "kitEngineRec(curP()).kind") == "managed" and "USD" in ev(pg, "t('kit.e.managed')"))
    check("drafts to approve → GitHub issues", ev(pg, "kitResultsRec(curP()).kind") == "issue")
    check("the Managed Agent option names the cost on the card", ev(pg, "(() => { const x = queueOf(curP()).find(x => x.kind === 'kit-engine'); return qOptions(curP(), x).find(o => o.star).label; })()") == ev(pg, "t('kit.e.managed')"))
    ev(pg, "(() => { const p = curP(); p.intake.raw = 'Every morning check three shop pages for price drops and tell me'; p.northStar.goal = 'Tell me about price drops every morning'; })()")
    n0 = ev(pg, "curP().decisions.length"); a0 = ev(pg, "arr(curP().acts).filter(a => !a.undone).length")
    ev(pg, "(async () => { for (const kind of ['kit-engine', 'kit-results']){ const x = queueOf(curP()).find(x => x.kind === kind); await qDo(curP(), x, qOptions(curP(), x).findIndex(o => o.star)); } })()"); pg.wait_for_timeout(60)
    check("two clicks decide both: two decision lines, two Undo steps, queue empty of kit items", ev(pg, "curP().decisions.length") == n0 + 2 and ev(pg, "arr(curP().acts).filter(a => !a.undone).length") == a0 + 2 and ev(pg, "!queueOf(curP()).some(x => x.kind.startsWith('kit-'))"), ev(pg, "arr(curP().acts).filter(a => !a.undone).map(a => a.label)"))
    check("stored as your decisions following the recommendation", ev(pg, "[kitRead(curP()).engine.kind, kitRead(curP()).results.kind, kitRead(curP()).engine.rec]") == ["scheduled", "page", "scheduled"])
    pr = ev(pg, "buildPrompt('architecture', {proj: curP(), rules: ['simple'], body: 'design', schema: '{}'})")
    check("the design prompt gets the scheduled facts, both decisions and the watchdog (daily)", "<kit_scheduled" in pr and pr.count("DECIDED by the person") == 2 and "Watchdog: ON" in pr and "<kit_artifact" not in pr)
    brief = ev(pg, "buildBriefText(curP())")
    check("the brief has the scheduled step, the results step and the watchdog step, and PART G", "Scheduled tool · Firnlab kit 2" in brief and "Where results land" in brief and "Watchdog (runs daily or more)" in brief and "PART G" in brief and "Firnlab kit 1" not in brief)
    ev(pg, "(() => { const p = curP(); p.intake.raw = 'Every Sunday summarise my week'; p.northStar.goal = 'A weekly summary'; })()")
    check("weekly → no watchdog step", "Watchdog (runs daily or more)" not in ev(pg, "buildBriefText(curP())") and "not needed at this cadence" in ev(pg, "buildPrompt('compile', {proj: curP(), rules: ['simple'], body: 'c', schema: '{}'})"))
    check("the proof-of-life rule applies to scheduled tools", "alive" in ev(pg, "proofModes(curP()).map(m => m.id)"))
    ev(pg, "kitSetEngine(curP(), 'managed')")
    check("a changed engine marks the scheduled sections only once a package exists (none yet → no flags)", ev(pg, "arr(curP().flags).length") == 0)
    ev(pg, ARCH, ["artifact page and a scheduled task", {"raw": "A board of price drops, checked every morning", "northStar": {"problem": "", "goal": "A board of price drops", "success": "", "users": "me", "constraints": "", "now": ""}}])
    check("page + schedule → both kits, results recommended on the page", ev(pg, "kitApplies(curP()) && kit2Applies(curP()) && kitResultsRec(curP()).kind === 'page'"))
    pr = ev(pg, "buildPrompt('compile', {proj: curP(), rules: ['simple'], body: 'c', schema: '{}'})")
    check("both blocks once each", pr.count("<kit_artifact") == 1 and pr.count("<kit_scheduled") == 1)

    print("9 kit 6: AI company")
    ev(pg, "(() => { newProject('Untitled', {raw: ''}); UI.home = false; render(); })()")
    check("ordinary pasted text stays Pick's import", not ev(pg, "looksLikeCompanyRecord('We decided weekly lists and a page with filters')"))
    rec = "MASTER RECORD\n" + "\n".join(f"SR-{i}: rule number {i} about the founder gate and budget" for i in range(1, 15)) + "\nManager, Architect, Secretary, Coach."
    check("a master record is recognised", ev(pg, "looksLikeCompanyRecord(arguments[0])", rec) if False else ev(pg, "(r) => looksLikeCompanyRecord(r)", rec))
    ev(pg, "(r) => aiPickImport(curP(), r)", rec); pg.wait_for_timeout(1200)
    co = ev(pg, "companyOf(curP())")
    check("the import went the company way: a company with a background job", co and co["kind"] == "company" and ev(pg, "isCompany(curP())"), co)
    check("the record was stored for the runner in the workspace's records", ev(pg, "(() => { const j = WS.jobs.find(j => j.kind === 'company'); return !!j && /\\/records\\//.test(j.inputs.record); })()"))
    pg.wait_for_timeout(1500)
    co = ev(pg, "companyOf(curP())")
    check("the job result laid out the company: name, goal, roles, founder question", ev(pg, "curP().name") == "Clearview Eyewear" and "1,000,000" in ev(pg, "curP().northStar.goal") and len(co["roles"]) == 3 and len(co["founderQs"]) == 1, co)
    reqs = ev(pg, "curP().requirements.map(r => [r.rule, r.priority, r.cat])")
    check("rules became must-requirements with the record's ids; a soft rule is 'should'", reqs == [["SR-3", "must", "gate"], ["SR-29", "must", "spend"], ["SR-175", "must", "budget"], ["SR-9", "should", "quality"]], reqs)
    check("decisions from the record are decision lines; a contradiction is an open question", ev(pg, "curP().decisions.some(d => d.title === 'Which product first?') && curP().openQs.some(q => /SR-12/.test(q.text))"))
    qs = ev(pg, "queueOf(curP()).filter(x => x.kind.startsWith('kit-') || x.kind.startsWith('co-')).map(x => [x.kind, x.cls])")
    check("the queue: the record decision, the founder question (hard, blocks), roles without tools", sorted(qs) == [["co-founderq", "block"], ["co-noemp", "should"], ["kit-record", "should"]], qs)
    check("record: few agents, no customer data → pages + GitHub recommended", ev(pg, "kitRecordRec(curP()).kind") == "pages")
    ev(pg, "(() => { curP().intake.raw = 'We hold customer data and orders'; })()")
    check("customer data → Supabase recommended, cost named on the option", ev(pg, "kitRecordRec(curP()).kind") == "supabase" and "USD 25" in ev(pg, "t('kit.rc.supabase')"))
    ev(pg, "(() => { curP().intake.raw = ''; })()")
    n = ev(pg, "companyMakeEmployees(curP())")
    emps = ev(pg, "companyEmployees(curP()).map(e => [companyOf(e).role, companyOf(e).system, e.mode, e.name])")
    check("one linked tool per role, in Pick, named after the company", n == 3 and len(emps) == 3 and all(e[2] == "pick" and e[3].startswith("Clearview Eyewear · ") for e in emps), emps)
    check("making them again adds nothing", ev(pg, "companyMakeEmployees(curP())") == 0 and ev(pg, "companyEmployees(curP()).length") == 3)
    check("the company panel shows in Pick with the employees", ev(pg, "(() => { curP().mode = 'pick'; render(); const el = document.querySelector('.pk-company'); return !!el && el.innerText.includes('Manager') && el.innerText.includes('Secretary'); })()"))
    ev(pg, "(() => { const q = companyOf(curP()).founderQs[0]; companyAnswer(curP(), q.id, 'Switzerland first'); })()")
    check("a founder answer closes the question and is a decision", ev(pg, "companyOf(curP()).founderQs[0].done && curP().decisions.slice(-1)[0].choice === 'Switzerland first' && !queueOf(curP()).some(x => x.kind === 'co-founderq')"))
    ev(pg, "(() => { const a = arr(curP().acts).filter(a => !a.undone).slice(-1)[0]; undoAct(curP(), a.id); })()")
    check("Undo reopens the founder question", ev(pg, "!companyOf(curP()).founderQs[0].done && queueOf(curP()).some(x => x.kind === 'co-founderq')"))
    ev(pg, "kitSetRecord(curP(), 'pages')")
    pr = ev(pg, "buildPrompt('architecture', {proj: curP(), rules: ['simple'], body: 'design', schema: '{}'})")
    check("the company prompt: facts, free infrastructure until launch, the gate, the roles, the record decision, the earlier platform's limits", "<kit_company" in pr and "free infrastructure" in pr and "nothing paid before launch" in pr and "Approve / Reject" in pr and "Secretary" in pr and "DECIDED by the founder" in pr and "GenSpark had no public API" in pr)
    brief = ev(pg, "buildBriefText(curP())")
    check("the company brief: record, founder gate, deployments + budget, PART H", "Company record · Firnlab kit 6" in brief and "Founder gate" in brief and "Free infrastructure until launch" in brief and "no API key, no paid tier, no domain" in brief and "PART H" in brief and "firnlab/clearview-eyewear" in brief)
    check("the zero-spend rule applies to the company", "spend" in ev(pg, "proofModes(curP()).map(m => m.id)"))
    ev(pg, "(() => { const e = companyEmployees(curP())[0]; ACTIONS['co-open']({dataset: {id: e.id}}); })()")
    check("an employee knows its company", ev(pg, "isEmployee(curP()) && companyOfEmployee(curP()).name === 'Clearview Eyewear'"))
    pr = ev(pg, "buildPrompt('compile', {proj: curP(), rules: ['simple'], body: 'c', schema: '{}'})")
    check("an employee's prompt inherits the company rules, its role and wall", "<kit_company_employee" in pr and "role Manager" in pr and "wall B2C" in pr and "[SR-29|spend]" in pr)
    ev(pg, "(() => { const p = curP(); p.arch.components = [{id: 'c1', name: 'Planner', kind: 'ai', role: 'plans the week', inputs: 'x', outputs: 'y', reason: '', reqIds: []}]; p.arch.options = [{id: 'o1', name: 'x', kind: 'agent', summary: '', scores: {}, pros: [], cons: []}]; p.arch.chosen = 'o1'; })()")
    check("an employee's brief has its step and inherits the rules in PART H", "Employee of Clearview Eyewear" in ev(pg, "buildBriefText(curP())") and "Inherited rules" in ev(pg, "buildBriefText(curP())"))
    check("the employee panel links back to the company", ev(pg, "(() => { render(); const el = document.querySelector('.pk-company'); return !!el && el.innerText.includes('Clearview Eyewear'); })()"))
    ev(pg, "(() => { openProject(companyOfEmployee(curP()).id); })()")

    print("10 kit 3: web apps and payments")
    ev(pg, "(() => { newProject('Recipe shop', {raw: 'A website where people subscribe and pay CHF 5 a month for my recipes'}); UI.home = false; render(); })()")
    ev(pg, ARCH, ["code repository (web app)", {"raw": "A website where people subscribe and pay CHF 5 a month for my recipes", "northStar": {"problem": "", "goal": "Sell recipe subscriptions worldwide", "success": "", "users": "home cooks", "constraints": "", "now": ""}}])
    check("a web app with payments → kit 3, not kit 1", ev(pg, "kit3Applies(curP()) && !kitApplies(curP()) && kit3Pays(curP()) && kit3Logs(curP())"))
